{
  "groups": [
    {
      "group_id": "vulnerable_repayment_stress",
      "rule": "credit_score_band == 'below_600' or (credit_score_band == '600_659' and credit_utilization_pct > 46.1)",
      "rationale": "Borrowers with low credit scores or high utilization are at elevated risk of delinquency and may require proactive retention support."
    },
    {
      "group_id": "high_rate_sensitive_variable",
      "rule": "rate_type == 'variable' and mortgage_rate_pct > 5.0",
      "rationale": "Variable rate borrowers facing significant rate hikes are highly motivated to shop for fixed-rate alternatives elsewhere."
    },
    {
      "group_id": "prime_equity_builders",
      "rule": "credit_score_band == '720_plus' and mortgage_balance_cad < 422947",
      "rationale": "High credit quality borrowers with lower balances have significant equity and strong retention potential through tailored loyalty offers."
    },
    {
      "group_id": "life_event_movers",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Borrowers undergoing major life transitions are prone to reassessing their banking needs and mortgage arrangements."
    },
    {
      "group_id": "stretched_large_families",
      "rule": "n_children >= 3 and adjusted_family_net_income_cad < 70582",
      "rationale": "Large households with limited net income may be highly price-sensitive and vulnerable to competing mortgage products."
    },
    {
      "group_id": "passive_locked_in",
      "rule": "rate_type == 'fixed' and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers currently benefiting from historically low fixed rates are unlikely to churn until their renewal window opens."
    },
    {
      "group_id": "investment_property_owners",
      "rule": "occupancy_type == 'rental' or occupancy_type == 'second_home'",
      "rationale": "Non-owner-occupied segments operate with different financial motivations compared to primary residents and require specialized engagement."
    },
    {
      "group_id": "engaged_high_net_worth",
      "rule": "has_investments == True and has_savings == True and household_income_cad > 137184",
      "rationale": "Affluent clients with multiple product relationships are stable but likely to seek competitive rate matching if they perceive a value gap."
    }
  ]
}
